import React, { useEffect, useRef, useImperativeHandle, forwardRef, useCallback } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";
import { Box } from "@mui/material";

const QrCodeScanner = forwardRef(({ handleScannerResult }, ref) => {
    const scannerRef = useRef(null);

    useEffect(() => {
        scannerRef.current = new Html5QrcodeScanner("reader", {
            qrbox: { width: 250, height: 250 },
            fps: 5,
        }, true);

        return () => {
            scannerRef.current?.clear().then(() => console.log("Scanner stopped"));
        };
    }, []);

    const startScanning = useCallback(() => {
        if (scannerRef.current) {
            const success = (result) => {
                scannerRef.current?.clear().then(() => console.log("Stopping video"));
                if (handleScannerResult) {
                    handleScannerResult(result);
                }
            };

            const error = (errorMessage) => {
                console.warn(errorMessage);
            };

            scannerRef.current.render(success, error);
        }
    }, [handleScannerResult]);

    useImperativeHandle(ref, () => ({
        startScanning,
    }));

    return (
        <Box>
            <div id="reader"></div>
        </Box>
    );
});

export default QrCodeScanner;
